import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Divider,
} from "@xco-agency/corex-ui";
import { PlanAvatar } from "./PlanAvatar";
import type { ActivePlanCardPropsType } from "../types";

export function ActivePlanCard({
  plan,
  interval = "monthly",
  statusText = "Active Subscription",
  statusTone = "info",
  billingNote = "Billed natively through your Shopify unified monthly invoice. Cancel anytime.",
  nextBillingDate,
  variant = "banner",
  annualDiscount,
  onChangePlan,
  onManageBilling,
}: ActivePlanCardPropsType) {
  const price = interval === "annual" ? plan.annualPrice : plan.monthlyPrice;

  if (variant === "card") {
    return (
      <Card>
        <BlockStack gap="base">
          {/* Main Header Row */}
          <InlineStack justifyContent="space-between" alignItems="center" gap="base" wrap>
            <InlineStack gap="base" alignItems="center">
              <PlanAvatar planId={plan.id} size={52} />

              <BlockStack gap="small-400">
                <InlineStack gap="small-200" alignItems="center" wrap>
                  <Text variant="headingMd" as="h2">
                    {plan.name} Plan
                  </Text>
                  <Badge tone={statusTone}>{statusText}</Badge>
                  {interval === "annual" && annualDiscount ? (
                    <Badge tone="success">{`Annual ${annualDiscount}% savings`}</Badge>
                  ) : null}
                </InlineStack>

                <Text variant="small" tone="neutral">
                  {billingNote}
                </Text>
              </BlockStack>
            </InlineStack>

            {/* Action Buttons */}
            <InlineStack gap="small-200" alignItems="center">
              {onManageBilling && (
                <Button variant="tertiary" onClick={onManageBilling}>
                  Manage Billing
                </Button>
              )}
              {onChangePlan && (
                <Button variant="secondary" onClick={onChangePlan}>
                  Change Plan
                </Button>
              )}
            </InlineStack>
          </InlineStack>

          <Divider />

          {/* Quick Stats Strip */}
          <InlineStack justifyContent="space-between" alignItems="center" gap="base" wrap>
            <InlineStack gap="small-300" alignItems="baseline">
              <Text variant="small" tone="neutral">
                Current Recurring Rate:
              </Text>
              <Text variant="bodyMd" fontWeight="bold">
                ${price} / month
              </Text>
              <Text variant="small" tone="neutral">
                ({interval === "annual" ? "billed annually" : "monthly cycle"})
              </Text>
            </InlineStack>

            {nextBillingDate && (
              <InlineStack gap="small-200" alignItems="center">
                <Text variant="small" tone="neutral">
                  Next Renewal:
                </Text>
                <Text variant="small" fontWeight="semibold">
                  {nextBillingDate}
                </Text>
              </InlineStack>
            )}
          </InlineStack>
        </BlockStack>
      </Card>
    );
  }

  // Default Banner Variant (matches user reference layout)
  return (
    <Card>
      <InlineStack justifyContent="space-between" alignItems="center" gap="base" wrap>
        {/* Left Side: Avatar + Plan Info */}
        <InlineStack gap="base" alignItems="center">
          <PlanAvatar planId={plan.id} size={48} />

          <BlockStack gap="small-500">
            <InlineStack gap="small-200" alignItems="center" wrap>
              <Text variant="bodyMd" fontWeight="bold">
                {plan.name} Plan
              </Text>
              <Badge tone={statusTone}>{statusText}</Badge>
            </InlineStack>

            <Text variant="small" tone="neutral">
              {billingNote}
            </Text>
          </BlockStack>
        </InlineStack>

        {/* Right Side: Action Button */}
        {onChangePlan && (
          <InlineStack alignItems="center">
            <Button variant="secondary" onClick={onChangePlan}>
              Change Plan
            </Button>
          </InlineStack>
        )}
      </InlineStack>
    </Card>
  );
}

import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Divider,
  Icon,
} from "@xco-agency/corex-ui";
import type { PricingCardPropsType } from "../types";
import { formatLimit, formatMoney, getAnnualSavings, getChangeKind } from "../utils";

export function PricingCard({
  plan,
  interval,
  isCurrent,
  currentPlan,
  onSelectPlan,
}: PricingCardPropsType) {
  const price = interval === "annual" ? plan.annualPrice : plan.monthlyPrice;
  const annualTotal = plan.annualPrice * 12;
  const savings = getAnnualSavings(plan);
  const kind = getChangeKind(currentPlan, plan);

  return (
    <Card>
      <BlockStack gap="base">
        {/* Header with Title & Badges */}
        <InlineStack alignItems="center" justifyContent="space-between" gap="small-200">
          <Text variant="large" heading>
            {plan.name}
          </Text>

          {isCurrent ? (
            <Badge tone="info">Current plan</Badge>
          ) : plan.badge ? (
            <Badge tone="success">{plan.badge}</Badge>
          ) : null}
        </InlineStack>

        <Text variant="small" tone="neutral">
          {plan.description}
        </Text>

        {/* Price Display */}
        <BlockStack gap="none">
          <InlineStack alignItems="baseline" gap="small-100">
            <Text variant="headingXl" heading>
              {formatMoney(price)}
            </Text>
            <Text as="span" variant="small" tone="neutral">
              / month
            </Text>
          </InlineStack>

          {interval === "annual" && plan.monthlyPrice > 0 ? (
            <InlineStack gap="small-200" alignItems="center">
              <Text variant="xs" tone="neutral">
                {formatMoney(annualTotal)} billed once per year
              </Text>
              <Badge tone="success">{`Save ${formatMoney(savings)}/yr`}</Badge>
            </InlineStack>
          ) : null}
        </BlockStack>

        {/* CTA Button */}
        {isCurrent ? (
          <Button variant="secondary" disabled>
            Current active plan
          </Button>
        ) : (
          <Button
            variant={plan.isPopular && kind === "upgrade" ? "primary" : "secondary"}
            onClick={() => onSelectPlan(plan)}
          >
            {`${kind === "upgrade" ? "Upgrade" : "Downgrade"} to ${plan.name}`}
          </Button>
        )}

        <Divider />

        {/* Key limits */}
        <BlockStack gap="small-300">
          <InlineStack justifyContent="space-between">
            <Text variant="small" color="subdued">
              Tracked orders
            </Text>
            <Text variant="small" fontWeight="semibold">
              {formatLimit("orders", plan)}
            </Text>
          </InlineStack>
          <InlineStack justifyContent="space-between">
            <Text variant="small" color="subdued">
              Cart add-ons
            </Text>
            <Text variant="small" fontWeight="semibold">
              {formatLimit("addOns", plan)}
            </Text>
          </InlineStack>
        </BlockStack>

        <Divider />

        {/* Features Checklist */}
        <BlockStack gap="small-200">
          <Text variant="xs" tone="neutral">
            INCLUDED WITH {plan.name.toUpperCase()}:
          </Text>

          {plan.features.map((feature, idx) => (
            <InlineStack key={idx} gap="small-200" alignItems="start">
              <Icon type={feature.included ? "check" : "minus"} size="small" />

              <Text as="span" color={feature.included ? "base" : "subdued"}>
                {feature.title}
              </Text>
            </InlineStack>
          ))}
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

import { BlockStack, Badge, Box, Card, Icon, Table, Text } from "@xco-agency/corex-ui";
import type { PricingComparisonTablePropsType } from "../types";
import { formatMoney, getPlanPrice } from "../utils";

/** Side-by-side plan comparison; the current plan's column is badged. */
export function PricingComparisonTable({
  plans,
  rows,
  interval,
  currentPlanId,
}: PricingComparisonTablePropsType) {
  return (
    <Card padding="none">
      <BlockStack>
        <Box padding="base">
          <BlockStack gap="none">
            <Text variant="base" heading>
              Compare plans
            </Text>
            <Text variant="small" color="subdued">
              Every limit and feature, side by side.
            </Text>
          </BlockStack>
        </Box>

        <Table variant="auto">
          <Table.HeaderRow>
            <Table.HeaderCell>Feature</Table.HeaderCell>
            {plans.map((plan) => (
              <Table.HeaderCell key={plan.id}>
                <BlockStack gap="small-500">
                  <Text variant="small" heading>
                    {plan.name}
                  </Text>
                  <Text variant="xs" color="subdued">
                    {plan.id === currentPlanId
                      ? "Current plan"
                      : `${formatMoney(getPlanPrice(plan, interval))} / mo`}
                  </Text>
                </BlockStack>
              </Table.HeaderCell>
            ))}
          </Table.HeaderRow>
          <Table.Body>
            {rows.map((row) => (
              <Table.Row key={row.label}>
                <Table.Cell>
                  <Text variant="small">{row.label}</Text>
                </Table.Cell>
                {plans.map((plan) => {
                  const value = row.values[plan.id];
                  return (
                    <Table.Cell key={plan.id}>
                      {typeof value === "boolean" ? (
                        <Icon
                          type={value ? "check" : "minus"}
                          size="small"
                          accessibilityLabel={value ? "Included" : "Not included"}
                        />
                      ) : (
                        <Text variant="small">{value}</Text>
                      )}
                    </Table.Cell>
                  );
                })}
              </Table.Row>
            ))}
          </Table.Body>
        </Table>
      </BlockStack>
    </Card>
  );
}

